head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS23500.xml';
//var vMktactCd = '309';		  //채권시장조치구분코드	
scwin.processGp;
scwin.vFrnidsApplStatCd = "1"; // 신청상태
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.obj_left = 0;
scwin.obj_top = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 목록조회
 ***********************************************/
scwin.fn_list_sync = function() {
    // 전체 초기화
    scwin.fn_ClearAll();
    var dsNm = 'BNS_FRNIDS_CHG_APPL_LIST';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsChgApplList';
    var param = '&{P}V_FRNIDS_APPL_STAT_CD=' + scwin.vFrnidsApplStatCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (tab_List.getSelectedTabIndex() == 1) {
        $c.cm.ShowWin(grd_List1);
    } else {
        $c.cm.ShowWin(grd_List2);
    }
};



/********************************************** 
 * 함수명    : fn_SearchT3
 * 설명       :  탭3 승인내역 조회
 ***********************************************/
scwin.fn_SearchT3 = function() {
    // 데이터셋 초기화
    dts_ChgApplListT3.removeAll();
    dts_FrnidsSchdlListT3.removeAll();
    var dsNm = "BNS_FRNIDS_CHG_PROCS_LIST";
    var qryId = "lds.stf.bnsfrn_mgr.select.selectFrnidsChgApplList3";
    var param = "&{P}V_PROCS_DD_FROM=" + $c.stf.getObjectValue(edt_ProcsDdFrom); //승인일자from
    param += "&{P}V_PROCS_DD_TO=" + $c.stf.getObjectValue(edt_ProcsDdTo); //승인일자to
    param += "&{P}V_PROCS_EMP_NM=" + $c.stf.getObjectValue(txb_ProcsEmpNm); //승인자
    param += "&{P}V_ACPT_EMP_NM=" + $c.stf.getObjectValue(txb_AcptEmpNm); //접수자
    param += "&{P}V_ISUR_CD=" + $c.stf.getObjectValue(txb_SearchIsurCd); //발행기관코드
    param += "&{P}V_ISUR_NM=" + $c.stf.getObjectValue(txb_SearchIsurNm); //발행기관명
    param += "&{P}V_ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd); //종목코드
    param += "&{P}V_ISU_NM=" + $c.stf.getObjectValue(txb_SearchIsuNm); //종목명

    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ListT3, dsNm, qryId, param);
    $c.cm.ShowWin(grd_ListT3);
};


/********************************************** 
 * 함수명    : fn_SelectApplDtlInfo
 * 설명       : 신청정보 상세조회
 ***********************************************/
scwin.fn_SelectApplDtlInfo = function() {
    var bnd_appl_id = dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID");
    var dsNm = 'BNS_FRNIDS_CHG_APPL_DTL';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsChgApplDtl';
    var param = '&{P}V_BND_APPL_ID=' + bnd_appl_id;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명    : fn_SelectApplScdList
 * 설명       : 신청스케쥴 목록 조회
 ***********************************************/
scwin.fn_SelectApplScdList = function() {
    // 승인인경우
    // 신고일정조회, 변경신청내역 조회
    // else 기존일정과 변경신청내역을 조합해서 조회.
    if (dts_List.getCellData(dts_List.getRowPosition(), "FRNIDS_APPL_STAT_CD") == "3") {
        scwin.fn_SelectApplScdList2();
    } else {
        scwin.fn_SelectApplScdList1();
    }
};



/********************************************** 
 * 함수명    : fn_SelectApplScdList1
 * 설명       : 기존일정과 변경신청내역을 조합해서 조회.
 ***********************************************/
scwin.fn_SelectApplScdList1 = function() {
    var bnd_appl_id = dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID");
    var std_cd = dts_List.getCellData(dts_List.getRowPosition(), "STD_CD");
    var dsNm = 'BNS_FRNIDS_CHG_APPL_SCD_LIST';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsChgApplScdList';
    var param = '&{P}V_BND_APPL_ID=' + bnd_appl_id;
    param += '&{P}V_STD_CD=' + std_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlScdList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명    : fn_SelectApplScdList2
 * 설명       : 신청스케쥴 목록 조회
 ***********************************************/
scwin.fn_SelectApplScdList2 = function() {
    var bnd_appl_id = dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID");
    var std_cd = dts_List.getCellData(dts_List.getRowPosition(), "STD_CD");
    var param = '&{P}V_BND_APPL_ID=' + bnd_appl_id;
    param += '&{P}V_STD_CD=' + std_cd;
    var dsNm = 'BNS_FRNIDS_CHG_APPL_SCD_LIST';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsChgApplScdList1';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ChgApplList, dsNm, qryId, param);
    var dsNm = 'BNS_FRNIDS_SCHDL_LIST';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsSchdlList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_FrnidsSchdlList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명    : fn_SelectApplScdList3
 * 설명       : 신청스케쥴 목록 조회
 ***********************************************/
scwin.fn_SelectApplScdList3 = function() {
    var bnd_appl_id = dts_ListT3.getCellData(dts_ListT3.getRowPosition(), "BND_APPL_ID");
    var std_cd = dts_ListT3.getCellData(dts_ListT3.getRowPosition(), "STD_CD");
    var param = '&{P}V_BND_APPL_ID=' + bnd_appl_id;
    param += '&{P}V_STD_CD=' + std_cd;
    var dsNm = 'BNS_FRNIDS_CHG_APPL_SCD_LIST';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsChgApplScdList1';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ChgApplListT3, dsNm, qryId, param);
    var dsNm = 'BNS_FRNIDS_SCHDL_LIST';
    var qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsSchdlList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_FrnidsSchdlListT3, dsNm, qryId, param);
};


/********************************************** 
 * 함수명    : fn_SelectBdchrgList
 * 설명       : 신고담당자 목록 조회
 ***********************************************/
scwin.fn_SelectBdchrgList = function() {
    var isur_cd = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_BdchrgList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "접수"))) return;
    scwin.processGp = "1"; // 접수

    var url = "/bns/IsuChgEtc.do?method=processFrnidsChgAppl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&PROCESS_STAT_CD=2"; // 처리상태코드, 2 : 접수, 3 : 승인

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo, I:pInput2=dts_DtlScdList)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    if (dts_List.getCellData(dts_List.getRowPosition(), "FRNIDS_APPL_STAT_CD") == "3") {
        $c.win.alert("이미 승인처리 되었습니다.");
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "승인"))) return;
    scwin.processGp = "3"; // 처리완료

    var url = "/bns/IsuChgEtc.do?method=processFrnidsChgAppl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&PROCESS_STAT_CD=3"; // 처리상태코드, 2 : 접수, 3 : 처리완료

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo, I:pInput2=dts_DtlScdList)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 첨부파일 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        DOWNLOAD_TP_CD: "FRNIDS" // 파일 다운로드시 필요
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetCommonKeyForList
 * 설명       : 상장신청시 첨부 팝업에 넘길 키데이터를 정의한다.
 *              :  실제 팝업에서는  BND_APPL_ID만 사용함.
 ***********************************************/
scwin.fn_GetCommonKeyForList = function(arrPar) {
    arrPar[0] = {
        //상장신청시 첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID_FOR_DOC"),
        BND_LIST_PROCS_TP_CD: "2",
        ISU_CD: dts_DtlInfo.getCellData(1, "STD_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        ISUR_NM: dts_DtlInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_DtlInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "STD_CD"),
        BND_LIST_PROCS_TP_CD: "1"
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 결재파일생성 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: gBndApplId,
        BND_LIST_PROCS_TP_CD: vBndListProcsTpCd,
        BND_MKTACT_TP_CD: vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_ProcBtnStat
 * 설명       : 처리 상태가 처리완료일 경우, 처리완료 버튼 비활성화
 ***********************************************/
scwin.fn_ProcBtnStat = function() {
    if (gProcsStat == "처리완료") {
        btn_Proc.src = "../img/bns/btn_20_d.gif";
        btnStat.Proc = "dis";
    } else {
        btn_Proc.src = "../img/bns/btn_20.gif";
        btnStat.Proc = "en";
    }
};




/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_CoupntRtCd, '03050'); //표면이자율결정 기준금리

};


/********************************************** 
 * 함수명   : fn_ClearAll
 * 설명      : 데이터셋 전체 초기화
 ***********************************************/
scwin.fn_ClearAll = function() {
    dts_List.removeAll();
    dts_DtlInfo.removeAll();
    dts_DtlScdList.removeAll();
    dts_BdchrgList.removeAll();
};


/******************************************************************* 
 * 함수명   : fn_PopReturn
 * 설명     : 반송처리 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopReturn = async function() {
    scwin.obj_left = 450;
    scwin.obj_top = 180;
    await $c.frame.CreateDialogFrame("ULDBNS23501", "/bnslistbzappl/ULDBNS23501.gfm", "반송처리", scwin.obj_left, scwin.obj_top, 420, 300, "window");
};


/******************************************************************* 
 * 함수명   : fn_ShowAttachFile
 * 설명     : 첨부문서 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_ShowAttachFile = async function(obj) {
    scwin.fn_GetPar = fn_GetCommonKey;
    scwin.obj_left = 450;
    scwin.obj_top = 180;
    await $c.frame.CreateDialogFrame("ULDBNS24501", "/bnslistbzappl/ULDBNS24501.gfm", "첨부문서 검색", scwin.obj_left, scwin.obj_top, 590, 310, "window");
};


/********************************************** 
 * 함수명   : fn_ProcBtnStat
 * 설명       : 처리 상태가 처리완료일 경우, 처리완료 버튼 비활성화
 ***********************************************/
scwin.fn_ProcBtnStat = function(isActive) {
    if (isActive) {
        btn_Proc.src = "../img/bns/btn_20.gif";
    } else {
        btn_Proc.src = "../img/bns/btn_20_d.gif";
    }
};



/**
 * 신청, 접수내역 중 변경신청 들어온 회차의 배경색을 Light Yellow로
 */
scwin.fn_ChangeGridBgColor = function() {
    //그리드 컬럼 ID 구하기
    var arrColID = [];
    for (var i = 0; i < grd_ScdList.getTotalCol(); i++) {
        arrColID.push(grd_ScdList.getColumnID(i));
    }

    //평가등급 일치여부가 N인 로우의 배경색 Light Yellow로 설정
    for (var j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_ScdList, arrColID[j], 'BgColor', "{decode(MODIFY_YN,'Y','#FFF7CC',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};



/**
 * 승인내역중 신청온건의 배경색을 빨간색으로..
 */
scwin.fn_ChangeGridBgColor1 = function() {
    $c.cm.setColumnProp(grd_ScdListAf, "INT_RT_CHG_DD", 'BgColor', "{decode(FIX_DD_CHG_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    $c.cm.setColumnProp(grd_ScdListAf, "INT_PAY_DD", 'BgColor', "{decode(PAY_DD_CHG_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");

    // tab3
    $c.cm.setColumnProp(grd_ScdListAfT3, "INT_RT_CHG_DD", 'BgColor', "{decode(FIX_DD_CHG_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    $c.cm.setColumnProp(grd_ScdListAfT3, "INT_PAY_DD", 'BgColor', "{decode(PAY_DD_CHG_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
};


/**
 * 신청상태에따른 그리드 visibility
 */
scwin.fn_GridControl = function() {
    if (tab_List.getSelectedTabIndex() == 1) {
        scwin.fn_GridControlType("A");
    } else {
        if (dts_List.getCellData(dts_List.getRowPosition(), "FRNIDS_APPL_STAT_CD") == "3") {
            // 승인인경우
            scwin.fn_GridControlType("B");
        } else {
            scwin.fn_GridControlType("A");
        }
    }
};




/**
 * 타입에따른  그리드 visibility
 */
scwin.fn_GridControlType = function(type) {
    if (type == "A") {
        grd_ScdList.style.display = "";
        panel_3.style.display = "none";
    } else {
        grd_ScdList.style.display = "none";
        panel_3.style.display = "";
    }
};



/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (!confirm("엑셀파일로 다운로드하시겠습니까?")) {
        return;
    }
    var excelSheet = '승인내역';
    if (dts_ListT3.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_ListT3, excelSheet, "", 8, 0);
    } else {
        $c.win.alert("데이터가 없습니다.");
    }
};



/********************************************** 
 * 함수명   : fn_GetParListBndIsu
 * 설명       : 상장종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: "1" // 1 : 상장종목만, 2 : 상장폐지도 포함, else : 모두
            ,
        ISUR_NM: "",
        ISU_NM: $c.stf.getObjectValue(txb_SearchIsuNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetParListBndIsu
 * 설명       : 상장종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParListBndIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_SearchIsuCd, arrPar[0].STD_CD);
    $c.stf.setObjectValue(txb_SearchIsuNm, arrPar[0].ISU_NM);
};


/********************************************** 
 * 함수명   : fn_ShowIsurPopup
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsurPopup = function(obj) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(obj);
};

/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_SearchIsurCd),
        ISUR_NM: $c.stf.getObjectValue(txb_SearchIsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_SearchIsurCd, arrPar[0].ISUR_CD);
    $c.stf.setObjectValue(txb_SearchIsurNm, arrPar[0].ISUR_NM);
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)
    $c.bns.BnsPanelToGroupBox(panel_Top); //패널라운드처리(접수)
    $c.bns.BnsPanelToGroupBox(panel_1);
    $c.bns.BnsPanelToGroupBox(panel_14);
    //BnsPanelToGroupBox(panel_T3);

    //fn_SetComboCode();

    edt_ProcsDdFrom.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 30));
    edt_ProcsDdTo.setValue($c.ut.cGetToday("yyyymmdd"));
    tab_List.setSelectedTabIndex(1);
    scwin.fn_GridControlType("A");
    scwin.fn_list_sync(); //목록 조회

    // 신청, 접수그리드의 신청건 배경색 변경
    scwin.fn_ChangeGridBgColor();

    // 승인내역중 신청건 배경색 변경
    scwin.fn_ChangeGridBgColor1();
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    // 그리드 visibility
    scwin.fn_GridControl();
    if (nIndex == 1) {
        panel_Top.style.display = "";
        scwin.vFrnidsApplStatCd = "1";
        scwin.fn_list_sync(); //목록 조회

    } else if (nIndex == 2) {
        panel_Top.style.display = "";
        scwin.vFrnidsApplStatCd = "2";
        scwin.fn_list_sync(); //목록 조회

    } else if (nIndex == 3) {
        panel_Top.style.display = "none";
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (tab_List.getSelectedTabIndex() == 1) {
        $c.cm.CloseWin(rowcount, grd_List1);
    } else {
        $c.cm.CloseWin(rowcount, grd_List2);
    }
};
scwin.dts_List_OnRowPosChanged = function(row) {
    // 그리드 visibility
    scwin.fn_GridControl();
    if (row > 0) {
        // 신청상세 조회
        scwin.fn_SelectApplDtlInfo();

        // 신청스케쥴 조회
        scwin.fn_SelectApplScdList();

        // 신고담당자 조회
        scwin.fn_SelectBdchrgList();
    }
};
scwin.dts_ListT3_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_ListT3);
};
scwin.dts_ListT3_OnRowPosChanged = function(row) {
    if (row > 0) {
        // 신청내역, 승인내역 조회
        scwin.fn_SelectApplScdList3();
    }
};
