scwin.btn_Ret_onclick = function() {
    if (dts_List.getTotalRow() <= 0) return;
    scwin.fn_GetPar = fn_GetReturn;
    scwin.fn_SetPar = fn_SetReturn;
    $c.bns.fn_PopReturn();
};
scwin.btn_Ret2_onclick = function() {
    if (dts_List.getTotalRow() <= 0) return;

    // 승인된건은 반송 불가.
    if (dts_List.getCellData(dts_List.getRowPosition(), "FRNIDS_APPL_STAT_CD") == "3") {
        $c.win.alert("승인처리된 건은 반송이 불가합니다.");
        return;
    }
    scwin.fn_GetPar = fn_GetReturn;
    scwin.fn_SetPar = fn_SetReturn;
    $c.bns.fn_PopReturn();
};
